// the write node may not carry the job fields through, so rebuild them from whichever prepare node ran
let j; try { j = $('Prepare job (portal)').first().json; } catch (e) { j = $('Prepare job (WhatsApp)').first().json; }
return [{ json: j }];

// shell-safe commands (names like O'Brien must not break out of the quotes)
const j = $('Job').first().json;
const q = (s) => "'" + String(s ?? '').replace(/'/g, "'\\''") + "'";
const dir = `/data/intro/${j.broker_id}/${j.language}/${j.take_id}`;
const raw = `/data/intro/_inbox/${j.broker_id}_${j.take_id}.${j.ext}`;
const retry = $input.first().json.retry === true;
const tr = `/data/intro/_inbox/${j.broker_id}_${j.take_id}.transcript.json`;
const media = $('Insert media rows (state: processing)').all().map(i => i.json);
const media_ids = media.map(m => m.id).join(',');
const version = media[0]?.version;
return [{ json: { ...j, dir, raw, tr, retry, media_ids, version,
  check_cmd: `node /opt/lv/automation/media/check.js ${q(raw)} --json || true`,
  pipeline_cmd: `${retry ? 'TARGET_MB=8 ' : ''}bash -c ${q(`/opt/lv/automation/media/pipeline.sh --in ${q(raw)} --out-dir ${q(dir)} --transcript ${q(tr)} --name ${q(j.adviser_name)} --practice ${q(j.practice_name)} --fsp ${q(j.fsp_number)} --lang ${q(j.language)} ${j.kind === 'audio' ? '--audio-only' : ''}; rc=$?; echo; if [ -f ${q(dir + '/result.json')} ]; then tr -d '\\n' < ${q(dir + '/result.json')}; else echo "{\\"ok\\":false,\\"system\\":true,\\"reason\\":\\"pipeline exit $rc\\"}"; fi; echo`)}` } }];

const j = $('Build commands').last().json;
let r = {}; try { r = JSON.parse(($json.stdout || '').trim().split('\n').filter(Boolean).pop()); } catch (e) { r = { ok: false, reason: 'We could not read this file. Try recording again.', issues: [] }; }
return [{ json: { ...j, raw_ok: !!r.ok, raw_reason: r.reason || '', raw_check: r } }];

// 1) keep the transcript as a file for captions.js  2) spoken-word FAIS gate (same banned list as deliverables/intro-media/rubric.md)
const j = $('Build commands').last().json;
const tr = $json; const text = (tr.text || (tr.segments || []).map(s => s.text).join(' ')).trim();
const BANNED = [['product', /\b(product|products|policy|policies|investment|funeral cover|income protection)\b/i], ['premium or money', /\b(premium|premiums|rand|per month|a month|percent|%)\b|\bR\s?\d/i], ['insurer', /\b(insurer|insurers|insurance compan(y|ies)|old mutual|sanlam|discovery|liberty|momentum|outsurance|hollard|assupol|metropolitan|clientele)\b/i], ['returns', /\b(returns?|yield|growth|performance)\b/i], ['guarantee', /\b(guarantee|guaranteed|guarantees|risk[- ]free)\b/i], ['best/cheapest', /\b(best|cheapest|cheap|lowest|number one|affordable|bargain)\b/i], ['advice', /\b(you should|you need to|you must|i recommend|i advise|my advice|switch to|take out)\b/i], ['urgency', /\b(limited|today only|hurry|last chance|act now|too late|spots? left|urgent)\b/i]];
const hits = BANNED.filter(([, re]) => re.test(text)).map(([k]) => k);
const lower = text.toLowerCase();
const warn = [];
if (j.practice_name && !lower.includes(String(j.practice_name).toLowerCase())) warn.push('practice name not spoken (it is in the lower-third)');
const buf = Buffer.from(JSON.stringify(tr));
const bin = await this.helpers.prepareBinaryData(buf, 'transcript.json', 'application/json');
return [{ json: { ...j, transcript_text: text, transcript_words: text.split(/\s+/).filter(Boolean).length, spoken_hits: hits, spoken_warn: warn, spoken_ok: hits.length === 0 }, binary: { data: bin } }];

const b = $('Spoken-word FAIS gate + transcript file').last().json;
let r; try { r = JSON.parse(($json.stdout || '').trim().split('\n').filter(Boolean).pop()); } catch (e) { r = { ok: false, system: true, reason: 'pipeline output unreadable' }; }
const issues = (r.check && r.check.issues) || [];
const oversize = issues.some(i => i.code === 'too_big');
// a check failure carries plain-English reasons; anything else (ffmpeg missing, no transcript) is a system failure -> ops alert
const system = r.system === true || (!r.ok && !issues.some(i => i.severity === 'error'));
return [{ json: { ...b, result: r, pipeline_ok: !!r.ok, oversize, retried: b.retry === true, system_failure: system } }];

const b = $('Parse pipeline result').last().json;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: { ...b, thumb_b64: buf.toString('base64') } }];

const b = $('Parse pipeline result').last().json;
let v = {}; try { const t = ($json.content || []).map(c => c.text || '').join(''); v = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) { v = { unavailable: true }; }
const noFace = v.face_present === false;
return [{ json: { ...b, picture: v, picture_reject: noFace, picture_reason: noFace ? "We couldn't see your face in the video. Face the window, put your face in the middle of the frame and record again." : '' } }];

const b = $('Parse pipeline result').last().json;
const base = ($env.INTRO_PUBLIC_BASE || 'https://media.sortmycover.co.za').replace(/\/$/, '');
const p = `${base}/intro/${b.broker_id}/${b.language}/v${b.version}`;
const ai = { state: 'ready', take_id: b.take_id, source: b.source, raw_check: b.raw_check, check: b.result.check, picture: b.picture || null, spoken_warn: b.spoken_warn, transcript_words: b.transcript_words };
return [{ json: { ...b, video_url: b.kind === 'video' ? `${p}/intro_${b.language}.mp4` : '', voice_url: `${p}/intro_${b.language}.ogg`, thumb_url: b.kind === 'video' ? `${p}/thumb_${b.language}.jpg` : '', ai_check: ai } }];

const j = $('Build commands').last().json;
const all = ['Parse pre-check','Spoken-word FAIS gate + transcript file','Parse pipeline result','Interpret picture check'].map(n => { try { return $(n).last().json; } catch (e) { return null; } }).filter(Boolean);
const last = all[all.length - 1] || j;
let reason = '', system = false, code_ = 'rejected';
if (last.raw_ok === false) { reason = last.raw_reason; code_ = 'raw_check'; }
else if (last.spoken_ok === false) { reason = `Something said on the recording can't be used in a lead message (it touches on: ${last.spoken_hits.join(', ')}). Please record again using your approved script.`; code_ = 'spoken_gate'; }
else if (last.picture_reject) { reason = last.picture_reason; code_ = 'picture'; }
else if (last.pipeline_ok === false) { reason = (last.result && last.result.reason) || 'We could not process this recording.'; system = !!last.system_failure; code_ = system ? 'system' : 'pipeline_check'; reason = system ? 'We hit a problem on our side processing this. We have been told and will fix it. You do not need to do anything yet.' : reason; }
return [{ json: { ...j, reject_reason: reason, system_failure: system, reject_code: code_, ai_check: { state: 'rejected', take_id: j.take_id, source: j.source, reason, code: code_ } } }];

